// Des: Tests for pa-robo-txtz: group choice, matching, status modes
// Flo: parse fixture for several agents > check path decisions > odd inputs
// I/O: robots text > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const robo = @import("pa-robo-txtz.zig"); const fixt = @import("te-fixt-html.zig");
fn arenNew() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
test "star group: longest rule wins, allow beats on tie, delay and sitemap read" { var aren = arenNew(); defer aren.deinit(); const rob = try robo.roboParse(aren.allocator(), fixt.robo, "otherbot/1.0"); try std.testing.expect(!robo.roboAllow(rob, "/private/x").okay); try std.testing.expect(robo.roboAllow(rob, "/private/open/page").okay); try std.testing.expect(!robo.roboAllow(rob, "/tmp/a").okay); try std.testing.expect(robo.roboAllow(rob, "/public").okay); try std.testing.expectEqual(@as(u32, 2000), rob.delz); try std.testing.expectEqual(@as(usize, 1), rob.maps.len); }
test "our own group beats star, anchors work" { var aren = arenNew(); defer aren.deinit(); const rob = try robo.roboParse(aren.allocator(), fixt.robo, "scra/0.1.0"); try std.testing.expect(robo.roboAllow(rob, "/private/x").okay); try std.testing.expect(!robo.roboAllow(rob, "/secret").okay); try std.testing.expect(robo.roboAllow(rob, "/secret/more").okay); const dec = robo.roboAllow(rob, "/secret"); try std.testing.expectEqualStrings("/secret$", dec.rule); }
test "badbot group denies everything" { var aren = arenNew(); defer aren.deinit(); const rob = try robo.roboParse(aren.allocator(), fixt.robo, "BadBot"); try std.testing.expect(!robo.roboAllow(rob, "/").okay); try std.testing.expect(robo.roboAllow(rob, "/robots.txt").okay); }
test "wildcards and empty disallow" { var aren = arenNew(); defer aren.deinit(); const rob = try robo.roboParse(aren.allocator(), "User-agent: *\nDisallow: /*.pdf$\nDisallow: /a*b*c\nDisallow:\n", "x"); try std.testing.expect(!robo.roboAllow(rob, "/docs/file.pdf").okay); try std.testing.expect(robo.roboAllow(rob, "/docs/file.pdf?x=1").okay); try std.testing.expect(!robo.roboAllow(rob, "/aXbYc").okay); try std.testing.expect(robo.roboAllow(rob, "/aXb").okay); }
test "multiple user-agent lines share one group, case-insensitive fields, BOM and CRLF" { var aren = arenNew(); defer aren.deinit(); const rob = try robo.roboParse(aren.allocator(), "\xEF\xBB\xBFUSER-AGENT: foo\r\nUser-Agent: scra\r\nDISALLOW: /x\r\n", "scra/1"); try std.testing.expect(!robo.roboAllow(rob, "/x/y").okay); }
test "no matching group allows all; status modes" { var aren = arenNew(); defer aren.deinit(); const rob = try robo.roboParse(aren.allocator(), "User-agent: other\nDisallow: /\n", "scra"); try std.testing.expect(robo.roboAllow(rob, "/").okay); try std.testing.expectEqual(robo.Mode.allo, robo.roboStat(404)); try std.testing.expectEqual(robo.Mode.deny, robo.roboStat(503)); try std.testing.expectEqual(robo.Mode.pars, robo.roboStat(200)); var down: robo.Robo = .{ .mode = .deny }; try std.testing.expect(!robo.roboAllow(down, "/a").okay); down.mode = .allo; try std.testing.expect(robo.roboAllow(down, "/a").okay); }
test "pathological wildcard pattern does not blow up" { var aren = arenNew(); defer aren.deinit(); const rob = try robo.roboParse(aren.allocator(), "User-agent: *\nDisallow: /a*a*a*a*a*a*a*a*a*a*b\n", "x"); const longz = "/" ++ "a" ** 5000; try std.testing.expect(robo.roboAllow(rob, longz).okay); }
